#include <stdint.h>

struct KGlyph {
  uint16_t code;   // 유니코드
  uint8_t w, h;    // 점 그림 크기
  int8_t xo, yo;   // 기준선 기준 위치 (yo는 위쪽이 음수)
  uint8_t adv;     // 다음 글자까지 거리
  uint32_t off;    // 점 데이터 시작 위치
};

struct KFont {
  const KGlyph *glyphs;
  uint16_t count;
  const uint8_t *bits;
  uint8_t ascent;
  uint8_t height;
};

